// TestSpecPinsS2Plant proves the real §2 is closed against a new rule
// without a row id. The plant lives in an overlay, never in the checkout.
func TestSpecPinsS2Plant(t *testing.T) {
	t.Parallel()
	root := repoRoot(t)
	base := os.DirFS(root)
	original, err := fs.ReadFile(base, "docs/SPEC-TABLES.md")
	if err != nil {
		t.Fatal(err)
	}
	const heading = "### 2.1 Pointers\n"
	if !strings.Contains(string(original), heading) {
		t.Fatal("§2.1 heading missing")
	}
	planted := strings.Replace(string(original), heading, heading+"A pointer must refuse a forged target.\n", 1)
	fsys := overlayFS{FS: base, over: map[string][]byte{"docs/SPEC-TABLES.md": []byte(planted)}}
	_, findings := checkSpecPins(specPinsInput{fsys: fsys, spec: "docs/SPEC-TABLES.md", roadmap: "docs/roadmap.sexp", pins: specPinRegistry})
	for _, finding := range findings {
		if strings.Contains(finding, "normative sentence without a row id (section \"2.1 Pointers\")") {
			return
		}
	}
	t.Fatalf("the planted unpinned §2 rule was accepted: %v", findings)
}
